sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
       if (registrationValidated) {
        return true;
    }

    var ga = new GlideAjax('x_1523510_alloca_0.AllocateNowUtils');
    ga.addParam('sysparm_name', 'hasActiveRegistration');


    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
			g_form.setReadOnly('base', true)
			g_form.setReadOnly('function', true)
            g_form.addErrorMessage(
                'You already have a registration in another base. You can only register again if the previous one was rejected.'
            );


        } 



    }); 
}
